class Solution:
    def maskPII(self, s: str) -> str:
        if '@' in s:
            name, domain = s.lower().split('@')
            return f"{name[0]}*****{name[-1]}@{domain}"
        digits = [ch for ch in s if ch.isdigit()]
        local = "".join(digits[-4:])
        n = len(digits)
        if n == 10:
            return f"***-***-{local}"
        prefix = '*' * (n - 10)
        return f"+{prefix}-***-***-{local}"

class Solution {
public:
    string maskPII(string s) {
        size_t at = s.find('@');
        if (at != string::npos) {
            string name = s.substr(0, at);
            string domain = s.substr(at + 1);
            for (char& c : name) c = tolower(c);
            for (char& c : domain) c = tolower(c);
            return string(1, name[0]) + "*****" + string(1, name.back()) + "@" + domain;
        }
        string digits = "";
        for (char c : s) if (isdigit(c)) digits += c;
        string local = digits.substr(digits.length() - 4);
        int n = digits.length();
        if (n == 10) return "***-***-" + local;
        return "+" + string(n - 10, '*') + "-***-***-" + local;
    }
};

class Solution {
    public String maskPII(String s) {
        if (s.contains("@")) {
            String[] parts = s.toLowerCase().split("@");
            String name = parts[0], domain = parts[1];
            return name.charAt(0) + "*****" + name.charAt(name.length() - 1) + "@" + domain;
        }
        StringBuilder digits = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) digits.append(c);
        }
        int n = digits.length();
        String local = digits.substring(n - 4);
        if (n == 10) return "***-***-" + local;
        StringBuilder sb = new StringBuilder("+");
        for (int i = 0; i < n - 10; i++) sb.append('*');
        sb.append("-***-***-").append(local);
        return sb.toString();
    }
}

var maskPII = function(s) {
    if (s.includes('@')) {
        const [name, domain] = s.toLowerCase().split('@');
        return `${name[0]}*****${name[name.length - 1]}@${domain}`;
    }
    const digits = s.replace(/\D/g, '');
    const local = digits.slice(-4);
    const n = digits.length;
    if (n === 10) return `***-***-${local}`;
    return `+${"*".repeat(n - 10)}-***-***-${local}`;
};
